import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import pkg from "../../package.json" with { type: "json" };
import { compilerPath } from "./paths.js";
import { postProcess } from "./stdlib.js";

export type ModuleType = "module" | "commonjs";

/** Options for the Purus compiler. */
export interface CompileOptions {
  /**
   * Include the "Generated by Purus" header comment in the output.
   * @default true
   */
  header?: boolean;
  /**
   * Enable strict mode (`"use strict";` at the top of the output).
   * @default true
   */
  strict?: boolean;
  /**
   * Output module format.
   * - `"module"` — ES Modules (default)
   * - `"commonjs"` — CommonJS (`require` / `module.exports`)
   * @default "module"
   */
  type?: ModuleType;
}

/** The Purus compiler version. */
export const version: string = pkg.version;

interface ExecError extends Error {
  stdout?: string | Buffer;
  stderr?: string | Buffer;
}

function detail(err: ExecError): string {
  return `${err.stdout || ""}${err.stderr || ""}`.trim();
}

function tempSourceFile(): string {
  return path.join(
    os.tmpdir(),
    `purus_${Date.now()}_${Math.random().toString(36).slice(2)}.purus`
  );
}

function removeQuietly(file: string): void {
  try {
    fs.unlinkSync(file);
  } catch {
    // ignore cleanup errors
  }
}

function runCompiler(args: string[]): string {
  return execFileSync(process.execPath, [compilerPath, ...args], {
    encoding: "utf8",
    stdio: ["pipe", "pipe", "pipe"],
    timeout: 30000,
  });
}

/** Compile Purus source code to JavaScript. */
export function compile(source: string, options: CompileOptions = {}): string {
  const { header = true, strict = true, type } = options;
  const tmpFile = tempSourceFile();
  try {
    fs.writeFileSync(tmpFile, source, "utf8");
    const args = ["build", "--stdout", "--no-header"];
    if (!strict) {
      args.push("--strict", "false");
    }
    if (type === "commonjs") {
      args.push("--type", "commonjs");
    }
    args.push(tmpFile);
    let result: string;
    try {
      result = runCompiler(args);
    } catch (err) {
      const e = err as ExecError;
      throw new Error(detail(e) || `Compile error: ${e.message}`);
    }
    result = postProcess(result);
    if (header) {
      return `// Generated by Purus ${version}\n${result}`;
    }
    return result;
  } finally {
    removeQuietly(tmpFile);
  }
}

/**
 * Check Purus source code for syntax errors.
 * @returns `true` if the syntax is valid
 * @throws {Error} If the source contains syntax errors
 */
export function check(source: string): true {
  const tmpFile = tempSourceFile();
  try {
    fs.writeFileSync(tmpFile, source, "utf8");
    runCompiler(["check", tmpFile]);
    return true;
  } catch (err) {
    const e = err as ExecError;
    throw new Error(`Syntax error: ${detail(e) || e.message}`);
  } finally {
    removeQuietly(tmpFile);
  }
}
